"""Observed-event to synthetic-experiment bridge.

The bridge compiles a research target into Tezcat's ordinary ExperimentVersion.
It carries dataset/signature identity in a manifest, while leaving the base
synthetic configuration and deterministic kernel untouched.
"""

from __future__ import annotations

from typing import Any, Dict, Iterable, Mapping, Optional

from tezcat import __version__
from tezcat.core.config import ExperimentConfig
from tezcat.experiments.schema import Arm, DesignSpec, ExperimentVersion, ModelCard
from tezcat.external.schemas import EventSignature, checksum, utc_now


DEFAULT_DEPENDENT_VARIABLES = [
    "max_drawdown", "realized_volatility", "total_trades", "total_volume", "total_return",
]


def compile_event_experiment(*, base_config: ExperimentConfig,
                              signature: EventSignature,
                              experiment_id: str,
                              name: str,
                              question: str,
                              hypothesis: str,
                              root_seed: Optional[int] = None,
                              replications: int = 2,
                              primary_metric: str = "realized_volatility",
                              dependent_variables: Optional[Iterable[str]] = None,
                              dataset_manifest: Optional[Mapping[str, Any]] = None) -> Dict[str, Any]:
    """Compile an external target into a standard, baseline ExperimentVersion.

    The signature is research context, not a parameter override.  A researcher
    can then make explicit mechanism variants through the ordinary DesignSpec
    and existing BatchRunner.  This function never starts a run.
    """
    dependent = list(dependent_variables or DEFAULT_DEPENDENT_VARIABLES)
    if primary_metric not in dependent:
        dependent.insert(0, primary_metric)
    design = DesignSpec(
        design_type="baseline", question=question, hypothesis=hypothesis,
        independent_variables=["external.dataset_id", "external.signature_id"],
        dependent_variables=dependent, primary_metric=primary_metric,
        control=Arm(name="observed_event_context", overrides={}),
        replications=max(1, replications),
    )
    model_card = ModelCard(
        purpose="Synthetic mechanism experiment constructed from an observed external event signature.",
        assumptions=[
            "external data is a target/context descriptor, not synthetic state",
            "the synthetic market remains generated by Tezcat's deterministic kernel",
            "a baseline version alone does not establish mechanism evidence",
        ],
        mechanisms=["researcher-declared mechanisms only"],
        calibration_status="uncalibrated: external signature is a target, not a fitted parameter set",
        validation_status="not validated until a complete synthetic batch is analyzed",
        failure_modes=["synthetic configuration may not reproduce the observed signature"],
        limitations=["prediction-market contract semantics may differ across providers", "no causal claim is implied"],
        claims_not_supported=["the external event was caused by any proposed mechanism", "synthetic results forecast the real market"],
    )
    external_context = build_external_context(signature, dataset_manifest)
    version = ExperimentVersion(
        experiment_id=experiment_id, name=name, config=base_config,
        design=design, root_seed=root_seed, model_card=model_card,
        external_context=external_context,
    )
    manifest = build_research_manifest(version, signature, dataset_manifest=dataset_manifest)
    return {"experiment": version, "manifest": manifest}


def build_external_context(signature: EventSignature,
                           dataset_manifest: Optional[Mapping[str, Any]] = None) -> Dict[str, Any]:
    """Build the stable, non-kernel identity of an observed external input."""
    source = dict(dataset_manifest or {})
    event_ids = list(source.get("event_ids") or [])
    market_ids = list(source.get("market_ids") or [signature.market_id])
    return {
        "data_class": "OBSERVED_CONTEXT",
        "dataset_id": signature.dataset_id,
        "dataset_checksum": source.get("normalized_checksum"),
        "raw_checksum": source.get("raw_checksum"),
        "provider": signature.provider,
        "event_id": event_ids[0] if event_ids else signature.metadata.get("event_id"),
        "event_ids": event_ids,
        "market_ids": market_ids,
        "time_window": dict(signature.window),
        "adapter_version": source.get("adapter_version", signature.signature_version),
        "schema_version": source.get("schema_version", signature.signature_version),
        "signature_id": signature.signature_id,
        "signature_hash": signature.checksum,
    }


def build_research_manifest(version: ExperimentVersion, signature: EventSignature,
                            dataset_manifest: Optional[Mapping[str, Any]] = None) -> Dict[str, Any]:
    """Create the external-data identity record linked to a normal experiment."""
    context = build_external_context(signature, dataset_manifest)
    payload = {
        "experiment_hash": version.research_hash,
        "dataset_id": context["dataset_id"],
        "dataset_hash": context["dataset_checksum"],
        "raw_dataset_hash": context["raw_checksum"],
        "provider": context["provider"],
        "event_id": context["event_id"],
        "event_ids": context["event_ids"],
        "market_ids": context["market_ids"],
        "time_window": context["time_window"],
        "adapter_version": context["adapter_version"],
        "schema_version": context["schema_version"],
        "config_hash": version.to_dict()["config_hash"],
        "seed_plan": version.design_matrix(),
        "state_hash": None,
        "event_hash": None,
        "signature_id": signature.signature_id,
        "signature_hash": signature.checksum,
        "created_at": utc_now(),
        "code_version": __version__,
    }
    return {**payload, "research_manifest_hash": checksum(payload)}
